/**
 * VNA Route Manual v3.0 - Chapter 3 Parser
 * Parses CHAPTER 3_NEW_AMD.docx (flight route tables across 7 regions).
 * Resolves Table 18 empty template trap, FORMCHECKBOX EDTO ticks,
 * multi-leg triangular routes, and exact Word table layouts.
 */



/**
 * Parses Chapter 3 .docx file or XML document.
 *
 * @param {Document|string} docXml - DOM document or raw XML string of word/document.xml
 * @returns {Promise<{ routes: Array, regions: Array, airportRouteIndex: Object }>}
 */
function parseChapter3Xml(docXml) {
  let xmlDoc = docXml;
  if (typeof docXml === 'string') {
    const parser = new DOMParser();
    xmlDoc = parser.parseFromString(docXml, 'text/xml');
  }

  const body = xmlDoc.getElementsByTagName('w:body')[0] || xmlDoc.querySelector('body');
  if (!body) {
    throw new Error('Invalid Word document: <w:body> not found in document.xml');
  }

  const children = Array.from(body.children);
  const routes = [];
  const regions = [];
  const regionMap = new Map();

  let currentRegion = {
    id: 'reg_gen',
    code: '3.3.2.0',
    title: 'General Routes',
    name: 'General',
    routeCount: 0
  };

  let globalRouteSeq = 1;

  for (let cIdx = 0; cIdx < children.length; cIdx++) {
    const child = children[cIdx];
    const localName = child.localName || child.nodeName.replace(/^w:/, '');

    // 1. Detect Section & Geographic Region Headings
    if (localName === 'p') {
      const pText = extractParagraphText(child);
      const regionMatch = pText.match(/^(3\.3\.2\.\d+)\s+(.+)$/);
      if (regionMatch) {
        const code = regionMatch[1];
        const rawTitle = regionMatch[2].trim();
        // Clean title (e.g. "North American routes" -> "North American")
        const cleanName = rawTitle.replace(/\s+routes$/i, '').trim();
        
        currentRegion = {
          id: `reg_${code.replace(/\./g, '_')}`,
          code: code,
          title: rawTitle,
          name: cleanName,
          fullHeading: pText,
          routeCount: 0
        };

        if (!regionMap.has(currentRegion.id)) {
          regionMap.set(currentRegion.id, currentRegion);
          regions.push(currentRegion);
        }
      }
      continue;
    }

    // 2. Parse Route Tables (<w:tbl>)
    if (localName === 'tbl') {
      const rows = getElementsByLocalName(child, 'tr');
      if (rows.length === 0) continue;

      // Check if table is just the 4-column column heading banner
      const firstRowCells = getElementsByLocalName(rows[0], 'tc');
      if (firstRowCells.length > 0) {
        const firstCellText = extractCellText(firstRowCells[0]).trim();
        if (firstCellText === 'No' || firstCellText.toLowerCase().includes('city pairs')) {
          // If only 1 or 2 rows, it's just a header banner table
          if (rows.length <= 2) continue;
        }
      }

      let rIdx = 0;
      while (rIdx < rows.length) {
        const row = rows[rIdx];
        const cells = getElementsByLocalName(row, 'tc');
        if (cells.length === 0) {
          rIdx++;
          continue;
        }

        const cell0Props = getCellProperties(cells[0]);
        const cell0Text = extractCellText(cells[0]);

        const isHeaderRow = isRouteHeaderRow(cell0Props, cell0Text, cells.length);

        if (isHeaderRow) {
          const rawTitle = cell0Text.trim();
          // Extract leading numbering e.g. "1. SGN - SFO - SGN" -> num "1", pair "SGN - SFO - SGN"
          let routeNo = String(globalRouteSeq);
          let cityPair = rawTitle;

          const numMatch = rawTitle.match(/^(\d+)[\.\s]+(.+)$/);
          if (numMatch) {
            routeNo = numMatch[1];
            cityPair = numMatch[2].trim();
          }

          rIdx++;

          const legs = [];
          const metadata = {};
          const rawTableRows = [];

          // Add title row to raw AST
          rawTableRows.push({
            type: 'title',
            text: rawTitle,
            routeNo: routeNo,
            cityPair: cityPair,
            bgColor: cell0Props.bgColor || '#262626'
          });

          // Scan all subsequent rows of this route block until next route header or table end
          while (rIdx < rows.length) {
            const nextRow = rows[rIdx];
            const nextCells = getElementsByLocalName(nextRow, 'tc');
            if (nextCells.length === 0) {
              rIdx++;
              continue;
            }

            const nextCell0Props = getCellProperties(nextCells[0]);
            const nextCell0Text = extractCellText(nextCells[0]);

            // If next row starts a new route block, stop
            if (isRouteHeaderRow(nextCell0Props, nextCell0Text, nextCells.length)) {
              break;
            }

            const cellTexts = nextCells.map(c => extractCellText(c).trim());

            // Check if this is a Leg Row:
            // Typically 5 cells: [No, Dep, Arr, Route Name, Dest Alternates]
            // Or 4 cells if cell 0 was vertically merged
            const isLegRow = (cellTexts.length >= 5 && isValidIcao(cellTexts[1]) && isValidIcao(cellTexts[2])) ||
                             (cellTexts.length === 4 && isValidIcao(cellTexts[0]) && isValidIcao(cellTexts[1]));

            if (isLegRow) {
              let depIcao, arrIcao, routeName, altStr;
              if (cellTexts.length >= 5) {
                depIcao = cellTexts[1].toUpperCase();
                arrIcao = cellTexts[2].toUpperCase();
                routeName = cellTexts[3];
                altStr = cellTexts[4];
              } else {
                depIcao = cellTexts[0].toUpperCase();
                arrIcao = cellTexts[1].toUpperCase();
                routeName = cellTexts[2];
                altStr = cellTexts[3];
              }

              const alternates = altStr
                ? altStr.split(/[,;\s]+/).map(s => s.trim().toUpperCase()).filter(s => isValidIcao(s))
                : [];

              const legObj = {
                dep: depIcao,
                arr: arrIcao,
                routeName: routeName,
                destAlternates: alternates,
                rawAlternatesStr: altStr || ''
              };

              legs.push(legObj);
              rawTableRows.push({
                type: 'leg',
                leg: legObj,
                rawTexts: cellTexts
              });
              rIdx++;
            } else if (cellTexts.length >= 2) {
              // Metadata Row (Label | Value)
              const rawLabel = cellTexts[0].replace(/\s+/g, ' ').trim();
              const rawValue = cellTexts[1];

              metadata[rawLabel] = rawValue;
              rawTableRows.push({
                type: 'meta',
                label: rawLabel,
                value: rawValue,
                rawTexts: cellTexts
              });
              rIdx++;
            } else {
              rIdx++;
            }
          }

          // EDGE CASE #2: Only save if route has a city pair and at least one leg
          if (cityPair && legs.length > 0) {
            const routeId = `R${String(routes.length + 1).padStart(3, '0')}`;
            
            // Extract enroute alternates into clean ICAO list
            const enrAltRaw = metadata['Preferred Enroute Alternate Airport'] ||
                              metadata['Preferred Enroute alternate Airport'] ||
                              metadata['Preferred Enroute Alternate Airports'] || '';
            const enrouteAlternates = enrAltRaw
              ? enrAltRaw.split(/[,;\s]+/).map(s => s.trim().toUpperCase()).filter(s => isValidIcao(s))
              : [];

            // Extract depressurization procedure (e.g. Europe routes)
            const depressVal = (metadata['Depressurization Procedure'] ||
                               metadata['Depressurization procedure'] ||
                               metadata['Depressurisation Procedure'] ||
                               metadata['Depressurisation procedure'] ||
                               metadata['Depressurization Procedures'] ||
                               metadata['Depressurisation Procedures'] ||
                               metadata['Depressurization'] ||
                               metadata['Depressurisation'] ||
                               getMetaCaseInsensitive(metadata, 'depressur') ||
                               getMetaCaseInsensitive(metadata, 'escape route') ||
                               '').trim();

            if (depressVal) {
              metadata['Depressurization Procedure'] = depressVal;
            }

            const route = {
              id: routeId,
              seq: globalRouteSeq,
              number: routeNo,
              cityPair: cityPair,
              region: currentRegion.name,
              regionCode: currentRegion.code,
              regionId: currentRegion.id,
              legs: legs,
              areaOperation: metadata['Area Operation'] || '',
              enrouteAlternates: enrouteAlternates,
              enrouteAlternatesRaw: enrAltRaw,
              rvsm: metadata['RVSM'] || 'Required',
              edto: metadata['EDTO'] || '',
              pbn: metadata['PBN'] || '',
              datalink: metadata['Datalink'] || '',
              flightLevel: metadata['Flight level'] || '',
              depressurization: depressVal,
              restriction: metadata['Restriction'] || '',
              metadata: metadata,
              rawMeta: metadata,
              rawTableRows: rawTableRows
            };

            routes.push(route);
            currentRegion.routeCount++;
            globalRouteSeq++;
          }
        } else {
          rIdx++;
        }
      }
    }
  }

  // Build Cross-Reference Airport -> Routes index
  const airportRouteIndex = buildAirportRouteIndex(routes);

  return {
    routes,
    regions: regions.filter(r => r.routeCount > 0),
    airportRouteIndex,
    routesCount: routes.length
  };
}

/**
 * Detects whether a table row is a route header row.
 * Handles all 7 geographic region shading colors and filters out template blanks and banner rows.
 */
function isRouteHeaderRow(props, text, cellCount) {
  if (!text) return false;
  const clean = text.replace(/-/g, '').trim();
  if (!clean) return false;
  const lower = text.toLowerCase();
  if (lower === 'no' || lower.includes('city pairs') || lower.includes('standard routes') || lower.includes('destination area operation')) {
    return false;
  }
  return (props.colspan >= 4 || cellCount === 1) && (text.includes('-') || props.bgColor != null);
}

/**
 * Validates whether a token is a plausible 4-letter ICAO code.
 */
function isValidIcao(token) {
  if (!token) return false;
  const clean = token.trim();
  return /^[A-Z]{4}$/i.test(clean);
}

/**
 * Builds an index of airports referencing routes where the airport is DEP, ARR, DEST ALT, or ENR ALT.
 */
function buildAirportRouteIndex(routes) {
  const index = {};

  for (const r of routes) {
    // Legs
    for (const leg of r.legs) {
      if (leg.dep) addEntry(index, leg.dep, r.id, 'dep');
      if (leg.arr) addEntry(index, leg.arr, r.id, 'arr');
      for (const alt of leg.destAlternates) {
        addEntry(index, alt, r.id, 'dest-alt');
      }
    }
    // Enroute alternates
    for (const enr of r.enrouteAlternates) {
      addEntry(index, enr, r.id, 'enr-alt');
    }
  }

  return index;
}

function addEntry(index, icao, routeId, role) {
  const code = icao.toUpperCase();
  if (!index[code]) {
    index[code] = {
      dep: new Set(),
      arr: new Set(),
      destAlt: new Set(),
      enrAlt: new Set(),
      allRoutes: new Set()
    };
  }

  if (role === 'dep') index[code].dep.add(routeId);
  else if (role === 'arr') index[code].arr.add(routeId);
  else if (role === 'dest-alt') index[code].destAlt.add(routeId);
  else if (role === 'enr-alt') index[code].enrAlt.add(routeId);
  index[code].allRoutes.add(routeId);
}

function getMetaCaseInsensitive(meta, query) {
  if (!meta) return '';
  const q = query.toLowerCase();
  for (const k of Object.keys(meta)) {
    if (k.toLowerCase().includes(q)) {
      return meta[k];
    }
  }
  return '';
}

// --- MODULE: parsers/chapter4Parser.js ---
/**
 * VNA Route Manual v3.0 - Chapter 4 Parser
 * Parses CHAPTER 4_REV04.docx (278 airports, 397 tables, 328 embedded charts).
 * Handles tracked deletions (<w:del>) skipping in EKBI, ENGM, ESGG, ESSA,
 * Heading2 stop boundary after ZYTX, two-table merging, and lazy media extraction.
 */



/**
 * Parses Chapter 4 document.xml and document.xml.rels
 *
 * @param {Document|string} docXml - DOM document or raw XML string of word/document.xml
 * @param {string} [relsXmlStr] - Raw XML string of word/_rels/document.xml.rels
 * @returns {{ airports: Array, supplementarySections: Array, relMap: Object, stats: Object }}
 */
function parseChapter4Xml(docXml, relsXmlStr = '') {
  let xmlDoc = docXml;
  if (typeof docXml === 'string') {
    const parser = new DOMParser();
    xmlDoc = parser.parseFromString(docXml, 'text/xml');
  }

  // Parse Relationship map (rId -> word/media/imageXX.png)
  const relMap = parseRelationships(relsXmlStr);

  const body = xmlDoc.getElementsByTagName('w:body')[0] || xmlDoc.querySelector('body');
  if (!body) {
    throw new Error('Invalid Word document: <w:body> not found in Chapter 4 document.xml');
  }

  const children = Array.from(body.children);
  const airports = [];
  const supplementarySections = [];

  let currentAirport = null;
  let currentSuppSection = null;
  let totalImagesCount = 0;

  for (let cIdx = 0; cIdx < children.length; cIdx++) {
    const child = children[cIdx];
    const localName = child.localName || child.nodeName.replace(/^w:/, '');

    // 1. PARAGRAPH ANALYSIS (<w:p>)
    if (localName === 'p') {
      const pPr = getChildByLocalName(child, 'pPr');
      let pStyle = '';
      if (pPr) {
        const pStyleEl = getChildByLocalName(pPr, 'pStyle');
        if (pStyleEl) {
          pStyle = getAttrVal(pStyleEl, 'val') || '';
        }
      }

      const pText = extractParagraphText(child);

      // Check for Airport Heading (Heading3 or text matching "ICAO / IATA - NAME - COUNTRY")
      // e.g. "CYVR / YVR - VANCOUVER INTL - CANADA" or "LFBO/ TLS BLAGNAC AIRPORT - TOULOUSE, FRANCE"
      const aptMatch = pText.match(/^([A-Z0-9]{4})\s*\/\s*([A-Z0-9]{3})\s*(?:[-–—]\s*|\s+)(.+)$/i);

      if (aptMatch && (pStyle.toLowerCase().includes('heading3') || pStyle === 'Heading3' || !pStyle)) {
        // Save previous airport if active
        if (currentAirport) {
          finalizeAirport(currentAirport);
          airports.push(currentAirport);
        }

        const icao = aptMatch[1].toUpperCase();
        const iata = aptMatch[2].toUpperCase();
        const rawNameCountry = aptMatch[3].trim();
        const parts = rawNameCountry.split(/[-–—]/).map(s => s.trim());
        const name = parts[0] || rawNameCountry;
        const country = parts.length > 1 ? parts.slice(1).join(' - ') : '';

        currentAirport = {
          id: `apt_${icao}`,
          index: airports.length + 1,
          icao: icao,
          iata: iata,
          name: name,
          country: country,
          fullHeading: pText,
          // Structured fields (Items 1-10)
          category: '',
          rffsCategory: '',
          classification: {},
          generalStandards: '',
          departure: '',
          arrival: '',
          taxi: '',
          parking: '',
          runways: [],
          elevation: '',
          eosid: '',
          iap: '',
          companyNote: '',
          remark: '',
          // Table ASTs and attached diagrams
          tables: [],
          images: [],
          hasImages: false
        };

        currentSuppSection = null;
        continue;
      }

      // CRITICAL STOP RULE: Check for Heading1 or Heading2 after ZYTX
      // Sections like: 4.3 AIRPORT FACILITIES, WEATHER MINIMA, LOW VISIBILITY OPERATION, NARROW RUNWAYS, TERMINAL CHARTS
      if (pStyle.toLowerCase().includes('heading1') || pStyle.toLowerCase().includes('heading2') ||
          pText.match(/^(4\.\d+|AIRPORT FACILITIES|WEATHER MINIMA|LOW VISIBILITY|NARROW RUNWAYS|TERMINAL CHARTS)/i)) {
        
        if (currentAirport) {
          finalizeAirport(currentAirport);
          airports.push(currentAirport);
          currentAirport = null;
        }

        if (pText.length > 2) {
          currentSuppSection = {
            title: pText,
            style: pStyle,
            tables: [],
            images: []
          };
          supplementarySections.push(currentSuppSection);
        }
        continue;
      }

      // Extract embedded images inside standalone paragraphs (e.g. EGLL, VVDB EOSID turn, ZYTX charts)
      const pImages = extractImagesFromNode(child, relMap, currentAirport ? currentAirport.icao : 'SUPP');
      if (pImages.length > 0) {
        if (currentAirport) {
          currentAirport.images.push(...pImages);
          currentAirport.hasImages = true;
          totalImagesCount += pImages.length;
        } else if (currentSuppSection) {
          currentSuppSection.images = currentSuppSection.images || [];
          currentSuppSection.images.push(...pImages);
        }
      }

      continue;
    }

    // 2. TABLE ANALYSIS (<w:tbl>)
    if (localName === 'tbl') {
      const parsedTable = parseTableAST(child, relMap, currentAirport ? currentAirport.icao : 'SUPP');

      // CRITICAL EDGE CASE #3: Skip Tracked Deletion Ghost Tables
      // If table has 0 non-empty text cells, it's a deleted tracked table
      if (!parsedTable || parsedTable.isEmpty) {
        continue;
      }

      if (currentAirport) {
        currentAirport.tables.push(parsedTable);
        // Link any images in table to airport
        if (parsedTable.images.length > 0) {
          currentAirport.images.push(...parsedTable.images);
          currentAirport.hasImages = true;
          totalImagesCount += parsedTable.images.length;
        }
        // Extract structured items from table rows
        extractStructuredDataFromTable(parsedTable, currentAirport);
      } else if (currentSuppSection) {
        currentSuppSection.tables.push(parsedTable);
      }
    }
  }

  // Finalize last airport if needed
  if (currentAirport) {
    finalizeAirport(currentAirport);
    airports.push(currentAirport);
  }

  return {
    airports,
    supplementarySections,
    relMap,
    stats: {
      airportsCount: airports.length,
      imagesCount: totalImagesCount,
      supplementarySectionsCount: supplementarySections.length
    }
  };
}

/**
 * Parses an OOXML <w:tbl> into a Table AST while computing rowspans and colspans.
 *
 * @param {Element} tblNode
 * @param {Object} relMap
 * @param {string} airportIcao
 * @returns {Object} Table AST
 */
function parseTableAST(tblNode, relMap, airportIcao) {
  const rowElements = getElementsByLocalName(tblNode, 'tr');
  if (rowElements.length === 0) return null;

  const rows = [];
  const tableImages = [];
  let totalNonEmptyChars = 0;

  // Active vertical merge tracking per logical column: colIndex -> { cellRef, rowspan }
  const activeMerges = new Map();

  for (let rIdx = 0; rIdx < rowElements.length; rIdx++) {
    const rowEl = rowElements[rIdx];
    const cellElements = getElementsByLocalName(rowEl, 'tc');
    const rowCells = [];
    let logicalCol = 0;

    for (let cIdx = 0; cIdx < cellElements.length; cIdx++) {
      const tcEl = cellElements[cIdx];
      const text = extractCellText(tcEl);
      totalNonEmptyChars += text.length;

      const props = getCellProperties(tcEl);

      // Resolve images with relMap
      const cellImages = [];
      if (props.images && props.images.length > 0) {
        for (const img of props.images) {
          const mediaPath = relMap[img.rId] || '';
          const resolvedImg = {
            rId: img.rId,
            mediaPath: mediaPath,
            airportIcao: airportIcao,
            filename: mediaPath.split('/').pop() || `diagram_${img.rId}.png`,
            label: `Sơ đồ ${airportIcao} (#${tableImages.length + cellImages.length + 1})`
          };
          cellImages.push(resolvedImg);
          tableImages.push(resolvedImg);
        }
      }

      const cellObj = {
        text: text,
        colspan: props.colspan,
        rowspan: 1,
        vMerge: props.vMerge,
        bgColor: props.bgColor,
        align: props.align,
        images: cellImages,
        isHiddenByRowspan: false
      };

      // Handle vertical merge calculation
      if (props.vMerge === 'restart') {
        activeMerges.set(logicalCol, cellObj);
      } else if (props.vMerge === 'continue') {
        if (activeMerges.has(logicalCol)) {
          const originCell = activeMerges.get(logicalCol);
          originCell.rowspan += 1;
          cellObj.isHiddenByRowspan = true;
        }
      } else {
        activeMerges.delete(logicalCol);
      }

      rowCells.push(cellObj);
      logicalCol += props.colspan;
    }

    rows.push({
      rowIndex: rIdx,
      cells: rowCells
    });
  }

  return {
    rows,
    images: tableImages,
    isEmpty: totalNonEmptyChars === 0 && tableImages.length === 0
  };
}

/**
 * Extracts normalized structured airport fields (Items 1-10) from parsed Table AST.
 */
function extractStructuredDataFromTable(tableAst, airport) {
  for (const row of tableAst.rows) {
    const cells = row.cells.filter(c => !c.isHiddenByRowspan);
    const cellTexts = cells.map(c => c.text.trim());
    const rowRaw = cellTexts.join(' ');

    // Item 1: AIRPORT CATEGORY: A/B/C
    const mCat = rowRaw.match(/AIRPORT\s+CATEGOR[Y]?\s*[:]?\s*([A-C])/i);
    if (mCat && !airport.category) {
      airport.category = mCat[1].toUpperCase();
    }

    // Item 2: RFFS CATEGORY
    const mRffs = rowRaw.match(/RFFS\s+CATEGORY\s*[:]?\s*(\d+)/i);
    if (mRffs && !airport.rffsCategory) {
      airport.rffsCategory = mRffs[1];
    }

    // Item 6: Elevation
    const mElev = rowRaw.match(/ELEVATION\s*[:]?\s*([^\s;,\/]+ft|\d+\s*ft|\d+)/i);
    if (mElev && !airport.elevation) {
      airport.elevation = mElev[1];
    }

    // Item 7: EOSID
    const mEosid = rowRaw.match(/EOSID\s*[:]?\s*(YES|NO|AVBL|NIL|[^\n;]+)/i);
    if (mEosid && !airport.eosid) {
      airport.eosid = mEosid[1].trim();
    }

    // Item 8: IAP
    if (rowRaw.includes('IAP:') || rowRaw.includes('8. IAP') || rowRaw.includes('Instrument approach')) {
      const val = rowRaw.replace(/^.*?(?:IAP|Instrument approach procedures)\s*[:]?\s*/i, '').trim();
      if (val && !airport.iap) airport.iap = val;
    }

    // Item 9: Company Note
    if (rowRaw.includes('COMPANY NOTE') || rowRaw.includes('9. COMPANY')) {
      const val = rowRaw.replace(/^.*?COMPANY\s+NOTE\s*[:]?\s*/i, '').trim();
      if (val && !airport.companyNote) airport.companyNote = val;
    }

    // Item 10: Remark
    if (rowRaw.includes('REMARK') || rowRaw.includes('10. REMARK')) {
      const val = rowRaw.replace(/^.*?REMARK\s*[:]?\s*/i, '').trim();
      if (val && !airport.remark) airport.remark = val;
    }

    // Item 4: General Standards (Departure, Arrival, Taxi, Parking)
    if (cellTexts.length >= 2) {
      const lbl = cellTexts[0].toLowerCase();
      if (lbl.includes('departure') && !airport.departure) airport.departure = cellTexts[1];
      else if ((lbl.includes('arrival') || lbl.includes('approach')) && !airport.arrival) airport.arrival = cellTexts[1];
      else if (lbl.includes('taxi') && !airport.taxi) airport.taxi = cellTexts[1];
      else if (lbl.includes('parking') && !airport.parking) airport.parking = cellTexts[1];
    }

    // Item 3: Fleet Classification Table (ATR | A320 | A321 | A350 | B787)
    if (cellTexts.length >= 5 && cellTexts.slice(0, 5).every(c => ['ADQ', 'ADEQ', 'NR', 'NO', 'NIL', 'YES', '-'].includes(c.toUpperCase()))) {
      airport.classification = {
        ATR: cellTexts[0].toUpperCase(),
        A320: cellTexts[1].toUpperCase(),
        A321: cellTexts[2].toUpperCase(),
        A350: cellTexts[3].toUpperCase(),
        B787: cellTexts[4].toUpperCase()
      };
    }

    // Item 5: Runway Rows (e.g. 07R/25L or 28R or 10)
    if (cellTexts.length >= 5 && cellTexts[0].match(/^\d{2}[LRC]?(\s*\/\s*\d{2}[LRC]?)?$/i)) {
      const rwyObj = {
        rwy: cellTexts[0],
        length: cellTexts[1] || '',
        width: cellTexts[2] || '',
        tora: cellTexts[3] || '',
        lda: cellTexts[4] || '',
        toda: cellTexts[5] || '',
        asda: cellTexts[6] || ''
      };
      // Avoid duplicate runway entries if multi-table repeated
      if (!airport.runways.some(r => r.rwy === rwyObj.rwy)) {
        airport.runways.push(rwyObj);
      }
    }
  }
}

/**
 * Cleans up and defaults structured fields for an airport.
 */
function finalizeAirport(airport) {
  if (!airport.category) airport.category = 'A';
  if (!airport.rffsCategory) airport.rffsCategory = '8';
  if (Object.keys(airport.classification).length === 0) {
    airport.classification = { ATR: 'ADQ', A320: 'ADQ', A321: 'ADQ', A350: 'ADQ', B787: 'ADQ' };
  }
  airport.imagesCount = airport.images.length;
}

/**
 * Extracts blip and imagedata image references from any DOM node (paragraph or cell).
 */
function extractImagesFromNode(node, relMap, airportIcao) {
  const images = [];
  const blips = getElementsByLocalName(node, 'blip');
  for (const blip of blips) {
    const rId = getAttrVal(blip, 'embed') || getAttrVal(blip, 'link');
    if (rId && relMap[rId]) {
      const mediaPath = relMap[rId];
      images.push({
        rId: rId,
        mediaPath: mediaPath,
        airportIcao: airportIcao,
        filename: mediaPath.split('/').pop() || `diagram_${rId}.png`,
        label: `Sơ đồ ${airportIcao} (${mediaPath.split('/').pop() || rId})`
      });
    }
  }

  const vImgs = getElementsByLocalName(node, 'imagedata');
  for (const imgData of vImgs) {
    const rId = getAttrVal(imgData, 'id') || getAttrVal(imgData, 'href');
    if (rId && relMap[rId] && !images.some(img => img.rId === rId)) {
      const mediaPath = relMap[rId];
      images.push({
        rId: rId,
        mediaPath: mediaPath,
        airportIcao: airportIcao,
        filename: mediaPath.split('/').pop() || `diagram_${rId}.png`,
        label: `Sơ đồ ${airportIcao} (${mediaPath.split('/').pop() || rId})`
      });
    }
  }

  return images;
}

// --- MODULE: db/idbStore.js ---
/**
 * VNA Route Manual v3.0 - IndexedDB Storage Layer
 * Manages client-side persistence for parsed Chapter 3 & 4 data,
 * raw docx ArrayBuffers, and lazy on-demand image Blob extraction.
 */

const DB_NAME = 'VNA_RouteManual_DB_v3';
const DB_VERSION = 1;

const STORES = {
  DATASETS: 'parsed_datasets',
  RAW_FILES: 'raw_docx_files',
  MEDIA_BLOBS: 'media_blobs'
};

// In-memory runtime cache for extracted Blob URLs
const memoryBlobUrlCache = new Map();

/**
 * Opens and initializes the IndexedDB database.
 * @returns {Promise<IDBDatabase>}
 */
function openDatabase() {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) {
      reject(new Error('IndexedDB is not supported in this browser environment.'));
      return;
    }

    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;

      if (!db.objectStoreNames.contains(STORES.DATASETS)) {
        db.createObjectStore(STORES.DATASETS, { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains(STORES.RAW_FILES)) {
        db.createObjectStore(STORES.RAW_FILES, { keyPath: 'name' });
      }
      if (!db.objectStoreNames.contains(STORES.MEDIA_BLOBS)) {
        db.createObjectStore(STORES.MEDIA_BLOBS, { keyPath: 'path' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

/**
 * Saves parsed Chapter 3 & Chapter 4 data to IndexedDB.
 *
 * @param {Object} ch3Data
 * @param {Object} ch4Data
 * @returns {Promise<void>}
 */
async function saveParsedDataset(ch3Data, ch4Data) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction([STORES.DATASETS], 'readwrite');
    const store = tx.objectStore(STORES.DATASETS);

    const record = {
      id: 'active_dataset',
      version: '3.0',
      updatedAt: new Date().toISOString(),
      ch3: ch3Data,
      ch4: ch4Data
    };

    const req = store.put(record);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

/**
 * Retrieves the stored parsed dataset from IndexedDB.
 *
 * @returns {Promise<Object|null>}
 */
async function getParsedDataset() {
  try {
    const db = await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORES.DATASETS], 'readonly');
      const store = tx.objectStore(STORES.DATASETS);
      const req = store.get('active_dataset');

      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => reject(req.error);
    });
  } catch (err) {
    console.warn('[IndexedDB] Failed to read cached dataset:', err);
    return null;
  }
}

/**
 * Stores a raw docx ArrayBuffer to IndexedDB.
 *
 * @param {string} name - e.g. 'CHAPTER 4_REV04.docx'
 * @param {ArrayBuffer} arrayBuffer
 * @returns {Promise<void>}
 */
async function saveRawDocxFile(name, arrayBuffer) {
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction([STORES.RAW_FILES], 'readwrite');
    const store = tx.objectStore(STORES.RAW_FILES);

    const record = {
      name: name,
      buffer: arrayBuffer,
      size: arrayBuffer.byteLength,
      updatedAt: new Date().toISOString()
    };

    const req = store.put(record);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

/**
 * Retrieves a stored raw docx ArrayBuffer.
 *
 * @param {string} name
 * @returns {Promise<ArrayBuffer|null>}
 */
async function getRawDocxFile(name) {
  try {
    const db = await openDatabase();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORES.RAW_FILES], 'readonly');
      const store = tx.objectStore(STORES.RAW_FILES);
      const req = store.get(name);

      req.onsuccess = () => {
        if (req.result && req.result.buffer) {
          resolve(req.result.buffer);
        } else {
          resolve(null);
        }
      };
      req.onerror = () => reject(req.error);
    });
  } catch (err) {
    console.warn('[IndexedDB] Could not retrieve raw file:', err);
    return null;
  }
}

/**
 * Lazy On-Demand Image Blob Extraction:
 * Extracts a specific image from the Chapter 4 docx ZIP archive on-demand,
 * caches it as a Blob URL, and returns the URL for display.
 *
 * @param {string} mediaPath - e.g. "word/media/image12.png"
 * @param {JSZip} [activeZipInstance] - Optional already-loaded JSZip instance
 * @returns {Promise<string>} Blob URL (e.g. blob:http://localhost/...)
 */
async function getMediaBlobUrl(mediaPath, activeZipInstance = null) {
  if (!mediaPath) return '';

  // 1. Check in-memory cache first (fastest)
  if (memoryBlobUrlCache.has(mediaPath)) {
    return memoryBlobUrlCache.get(mediaPath);
  }

  // 2. Check IndexedDB media store
  try {
    const db = await openDatabase();
    const cachedRecord = await new Promise((resolve) => {
      const tx = db.transaction([STORES.MEDIA_BLOBS], 'readonly');
      const store = tx.objectStore(STORES.MEDIA_BLOBS);
      const req = store.get(mediaPath);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });

    if (cachedRecord && cachedRecord.blob) {
      const blobUrl = URL.createObjectURL(cachedRecord.blob);
      memoryBlobUrlCache.set(mediaPath, blobUrl);
      return blobUrl;
    }
  } catch (e) {
    console.warn('[IndexedDB] Error checking media cache:', e);
  }

  // 3. Extract from JSZip instance on demand
  let zip = activeZipInstance;
  if (!zip) {
    if (typeof window.JSZip === 'undefined') {
      throw new Error('JSZip library is required for unpacking images from .docx archive.');
    }
    const rawBuffer = await getRawDocxFile('CHAPTER 4_REV04.docx');
    if (!rawBuffer) {
      throw new Error(`Raw document CHAPTER 4_REV04.docx is not cached in IndexedDB. Please re-upload.`);
    }
    zip = await window.JSZip.loadAsync(rawBuffer);
  }

  const zipEntry = zip.file(mediaPath);
  if (!zipEntry) {
    console.warn(`[IndexedDB] Media entry ${mediaPath} not found in zip archive.`);
    return '';
  }

  // Determine MIME type from extension
  const ext = mediaPath.split('.').pop().toLowerCase();
  const mimeMap = {
    png: 'image/png',
    jpg: 'image/jpeg',
    jpeg: 'image/jpeg',
    gif: 'image/gif',
    svg: 'image/svg+xml',
    emf: 'image/x-emf',
    wmf: 'image/x-wmf'
  };
  const mimeType = mimeMap[ext] || 'application/octet-stream';

  const blob = await zipEntry.async('blob');
  const typedBlob = new Blob([blob], { type: mimeType });
  const blobUrl = URL.createObjectURL(typedBlob);

  memoryBlobUrlCache.set(mediaPath, blobUrl);

  // Store Blob in IndexedDB in the background
  try {
    const db = await openDatabase();
    const tx = db.transaction([STORES.MEDIA_BLOBS], 'readwrite');
    const store = tx.objectStore(STORES.MEDIA_BLOBS);
    store.put({
      path: mediaPath,
      blob: typedBlob,
      mimeType: mimeType,
      size: typedBlob.size
    });
  } catch (err) {
    console.warn('[IndexedDB] Background media cache store error:', err);
  }

  return blobUrl;
}

/**
 * Clears all cached datasets and images from IndexedDB.
 * @returns {Promise<void>}
 */
async function clearIndexedDbCache() {
  memoryBlobUrlCache.clear();
  const db = await openDatabase();
  return new Promise((resolve, reject) => {
    const tx = db.transaction([STORES.DATASETS, STORES.RAW_FILES, STORES.MEDIA_BLOBS], 'readwrite');
    tx.objectStore(STORES.DATASETS).clear();
    tx.objectStore(STORES.RAW_FILES).clear();
    tx.objectStore(STORES.MEDIA_BLOBS).clear();

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

